using System.Security.Claims;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using RaceDay.Api.Data;using RaceDay.Api.DTOs;using RaceDay.Api.Models;
namespace RaceDay.Api.Controllers;
[ApiController][Route("api/events")]
public class EventsController(RaceDayDbContext db):ControllerBase{
 int UserId=>int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);
 [HttpGet]public async Task<IActionResult> List([FromQuery]string? location,[FromQuery]DateTime? date){var q=db.Events.Include(e=>e.Categories).ThenInclude(c=>c.Enrolments).AsQueryable();if(User.Identity?.IsAuthenticated==true && User.IsInRole("Organiser"))q=q.Where(e=>e.OrganiserID==UserId);if(!string.IsNullOrWhiteSpace(location))q=q.Where(e=>e.Location.Contains(location));if(date.HasValue)q=q.Where(e=>e.EventDate.Date==date.Value.Date);return Ok(await q.OrderBy(e=>e.EventDate).ToListAsync());}
 [HttpGet("{id:int}")]public async Task<IActionResult> Get(int id){var e=await db.Events.Include(x=>x.Categories).Include(x=>x.Organiser).FirstOrDefaultAsync(x=>x.EventID==id);return e==null?NotFound():Ok(e);}
 [Authorize(Roles="Organiser")][HttpPost]public async Task<IActionResult> Create(EventRequest r){var e=new Event{Name=r.Name,Description=r.Description,EventDate=r.EventDate,Location=r.Location,DistanceKm=r.DistanceKm,EventType=r.EventType,BannerImageURL=r.BannerImageURL,OrganiserID=UserId};db.Events.Add(e);await db.SaveChangesAsync();return CreatedAtAction(nameof(Get),new{id=e.EventID},e);}
 [Authorize(Roles="Organiser")][HttpPut("{id:int}")]public async Task<IActionResult> Update(int id,EventRequest r){var e=await db.Events.FindAsync(id);if(e==null)return NotFound();if(e.OrganiserID!=UserId)return Forbid();e.Name=r.Name;e.Description=r.Description;e.EventDate=r.EventDate;e.Location=r.Location;e.DistanceKm=r.DistanceKm;e.EventType=r.EventType;e.BannerImageURL=r.BannerImageURL;await db.SaveChangesAsync();return Ok(e);}
 [Authorize(Roles="Organiser")][HttpDelete("{id:int}")]public async Task<IActionResult> Delete(int id){var e=await db.Events.FindAsync(id);if(e==null)return NotFound();if(e.OrganiserID!=UserId)return Forbid();if(await db.Enrolments.AnyAsync(x=>x.Category!.EventID==id))return Conflict(new{message="Event has enrolments; deletion is blocked"});db.Events.Remove(e);await db.SaveChangesAsync();return NoContent();}
}
